import {rotations} from '../core.js';
export function rotationPlanner(f){if(![1,2,3].includes(f.water)||!Number.isFinite(f.horizon)||f.horizon<1||f.horizon>60||typeof f.annual!=='boolean'||!['agua','ciclo','ingreso'].includes(f.priority))return {version:'planner-2.0',status:'DATOS INSUFICIENTES',alternatives:[]};const alternatives=rotations(f);return {version:'planner-2.0',status:'EXPERIMENTAL',priority:f.priority,alternatives,recommended:alternatives.find(r=>r.reasons.length===0)?.name||null,perennial_action:'Conservar frutales establecidos; evaluar cobertura y conservación de suelo con un técnico.',method:'Filtrar restricciones duras → puntuar prioridad → ordenar candidatos viables',constraints:{annual_plot:f.annual,water_category:f.water,horizon_months:f.horizon},weights:{agua:'100 − demanda ordinal × 25',ciclo:'100 − meses × 5',ingreso:'potencial ordinal × 25'},limits:['No rotar mango/limón establecidos como anuales.','Ciclos, demanda y potencial económico son supuestos del prototipo.','Sin costos/precios ni turnos/volumen reales: no se estima rentabilidad o calendario de riego.']};}
